INSERT IGNORE INTO `posts` (`id`,`user_id`,`title`,`blocks`,`blocks_version`,`status`,`visibility`,`cover_url`,`summary`,`allow_share`,`allow_index`,`review_status`,`review_reason`,`published_at`,`deleted_at`,`like_count`,`comment_count`,`topic_ids`,`created_at`,`updated_at`) VALUES ('ad28b798-a67d-4e80-905f-ef43ce8e97ac','ea019255-b142-4f6c-a382-796ad3d7f7a5','8 周卧推进阶复盘：从 70kg 到 82.5kg','[{"id":"0d2819c2-2e1e-4cb2-b5d7-d29f59d2e31f","type":"paragraph","version":1,"props":{"text":"八周前卧推卡在 70kg，问题不是力量不够，而是每次训练都在“凭感觉”加重量。这次把每周的训练量、次数和体感都记下来之后，进步第一次变得可解释。"}},{"id":"a92491f3-2f09-4105-9b83-ce21224d5557","type":"heading","version":1,"props":{"level":2,"text":"八周里我改了三件事"}},{"id":"4713e7fb-a241-4e8c-bf8d-51c190307095","type":"list","version":1,"props":{"ordered":true,"items":["主项固定 4 组，最后一组才冲重量","辅助动作只保留两个，避免容量虚高","每周只加 2.5kg，宁慢勿断"]}},{"id":"b22a144c-06e8-4baa-8fbb-584552fb2ab4","type":"embed","version":1,"props":{"embedType":"session","refId":"132f6c40-b0e0-497e-8364-000a11afb9ed"}},{"id":"281670dc-e618-4a51-a7ab-6565958a6f4c","type":"heading","version":1,"props":{"level":2,"text":"数据之外的两点感受"}},{"id":"f94bf1a7-42e5-4950-9bc2-3f898c49904c","type":"quote","version":1,"props":{"text":"训练记录不是为了好看，而是为了让下一次训练有依据。"}},{"id":"79b30990-4b36-4ac1-b425-fa248b9f7224","type":"paragraph","version":1,"props":{"text":"肩胛稳定比想象中重要。每次卧推前做两组面拉，起桥和落杠都更稳。第八周测试 82.5kg×5，估算 1RM 约 96kg——不惊人，但它是这八周唯一没有断过的事情。"}},{"id":"3315ca37-99bb-4ddc-bce0-07a4f72008cf","type":"divider","version":1,"props":{}},{"id":"40a8a892-4dc2-45c4-b3ec-b933e0a8ff51","type":"embed","version":1,"props":{"embedType":"checkin","refId":"2026-10-15"}},{"id":"28da3f3e-4ff7-4194-ab49-0ba15cc74d51","type":"paragraph","version":1,"props":{"text":"下一个八周：卧推维持，深蹲补频率。所有数据会继续留在这里。"}}]',1,'published','public',NULL,'八周卧推训练记录与复盘：固定主项、减少辅助、每周只加 2.5kg。',1,1,'approved',NULL,'2026-10-15T08:18:39.560Z',NULL,0,0,'','2026-10-13T08:18:39.560Z','2026-10-15T08:18:39.560Z');
INSERT IGNORE INTO `posts` (`id`,`user_id`,`title`,`blocks`,`blocks_version`,`status`,`visibility`,`cover_url`,`summary`,`allow_share`,`allow_index`,`review_status`,`review_reason`,`published_at`,`deleted_at`,`like_count`,`comment_count`,`topic_ids`,`created_at`,`updated_at`) VALUES ('9a9d3ee3-f517-4098-8c97-9d23d9a26c29','ea019255-b142-4f6c-a382-796ad3d7f7a5','深蹲动作检查清单：从站距到呼吸','[{"id":"e845a731-e50f-4128-95ff-1c6b39b45a35","type":"paragraph","version":1,"props":{"text":"深蹲不是把杠铃扛起来再蹲下去。下面这份清单是我每次训练前都会过一遍的内容。"}},{"id":"c77257af-ce58-4c02-99ea-37ef19d9902c","type":"heading","version":1,"props":{"level":3,"text":"起杠前"}},{"id":"9aed97c4-f9d5-4002-afec-9cdccc236dd2","type":"todo","version":1,"props":{"items":[{"text":"脚掌三点着地，站距与肩同宽或略宽","done":true},{"text":"吸气收紧核心，肋骨下沉","done":true},{"text":"确认保护杆高度","done":false}]}},{"id":"2e9fdbf2-5dd8-467f-826a-9a8ce5d992d3","type":"heading","version":1,"props":{"level":3,"text":"下蹲与起身"}},{"id":"480337b2-e227-4096-8fa0-026785336833","type":"list","version":1,"props":{"ordered":false,"items":["膝盖跟随脚尖方向","髋部与肩同时上升","起身时不抬头，视线固定"]}},{"id":"703af364-43b6-49f0-9516-a4ebdf508b43","type":"embed","version":1,"props":{"embedType":"exercise","refId":"ex_8526c60f1d48"}},{"id":"6a3c0a4f-7083-4f8e-913b-18f388c6cbfc","type":"paragraph","version":1,"props":{"text":"这份清单只对自己负责，不构成任何训练建议。"}}]',1,'published','unlisted',NULL,'一份自用的深蹲训练前检查清单。',1,0,'approved',NULL,'2026-10-10T08:18:39.570Z',NULL,0,0,'','2026-10-08T08:18:39.570Z','2026-10-10T08:18:39.570Z');
INSERT IGNORE INTO `posts` (`id`,`user_id`,`title`,`blocks`,`blocks_version`,`status`,`visibility`,`cover_url`,`summary`,`allow_share`,`allow_index`,`review_status`,`review_reason`,`published_at`,`deleted_at`,`like_count`,`comment_count`,`topic_ids`,`created_at`,`updated_at`) VALUES ('8de879b9-68ab-4f71-ac9f-d599961c6435','ea019255-b142-4f6c-a382-796ad3d7f7a5','十月训练小结（草稿）','[{"id":"b6688d51-5bd5-49af-bae4-26266a332711","type":"paragraph","version":1,"props":{"text":"这个月总容量比上月高，但最后一周明显疲劳。先把睡眠补回来，再谈加重量。"}},{"id":"55565ff1-eabc-48cf-b34e-5510fe3bdfd8","type":"heading","version":1,"props":{"level":2,"text":"待补充"}}]',1,'draft','private',NULL,'十月训练小结草稿',1,0,'none',NULL,NULL,NULL,0,0,'','2026-10-18T08:18:39.574Z','2026-10-18T08:18:39.574Z');
